use super::LevelFilter;
use crate::{
    layer::{Context, Filter, Layer},
    registry::LookupSpan,
    sync::RwLock,
};
use std::{
    any::TypeId,
    cell::RefCell,
    collections::HashMap,
    marker::PhantomData,
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc, Weak,
    },
};
use tracing_core::{callsite::Identifier, span, Event, Interest, Metadata, Subscriber};

/// A layer with a filter that applies only to that layer and its children.
#[derive(Debug)]
pub struct Filtered<L, F, S> {
    layer: L,
    filter: F,
    id: FilterId,
    interests: RwLock<HashMap<Identifier, Interest>>,
    revision: Arc<AtomicUsize>,
    _s: PhantomData<fn(S)>,
}

/// Identifies a per-layer filter in stored span data.
#[doc(hidden)]
#[derive(Debug, Copy, Clone, Eq, PartialEq)]
pub struct FilterId(usize);

/// The filters that enabled a span or event.
#[doc(hidden)]
#[derive(Debug, Default, Clone)]
pub struct FilterMap {
    enabled: Vec<FilterId>,
    // Keep pending enabled decisions tied to the filters that produced them.
    // Weak references also invalidate decisions when a reload replaces a
    // whole layer, and avoid retaining dropped filters in thread-local state.
    revisions: Vec<(Weak<AtomicUsize>, usize)>,
}

/// Separate global restrictions from the interests of independent consumers.
#[doc(hidden)]
#[derive(Debug, Clone)]
pub struct FilterResult<T> {
    pub(crate) global: T,
    pub(crate) consumers: T,
}

// A stable downcast marker, including through erased and reloadable layers.
pub(crate) struct FilterMarker;
pub(crate) static FILTER_MARKER: FilterMarker = FilterMarker;

impl FilterId {
    fn new() -> Self {
        static NEXT_ID: AtomicUsize = AtomicUsize::new(1);
        let id = NEXT_ID.fetch_add(1, Ordering::Relaxed);
        assert_ne!(id, 0, "per-layer filter IDs exhausted");
        Self(id)
    }
}

impl FilterMap {
    pub(crate) fn enable(&mut self, id: FilterId) {
        if !self.enabled.contains(&id) {
            self.enabled.push(id);
        }
    }
    pub(crate) fn is_enabled(&self, id: FilterId) -> bool {
        self.enabled.contains(&id)
    }
    fn extend(&mut self, other: Self) {
        for id in other.enabled {
            self.enable(id);
        }
        self.revisions.extend(other.revisions);
    }
    fn watch(&mut self, revision: &Arc<AtomicUsize>) {
        self.revisions
            .push((Arc::downgrade(revision), revision.load(Ordering::Acquire)));
    }
    fn is_current(&self) -> bool {
        self.revisions.iter().all(|(revision, version)| {
            revision
                .upgrade()
                .map(|revision| revision.load(Ordering::Acquire) == *version)
                .unwrap_or(false)
        })
    }
}

impl<T: Clone> FilterResult<T> {
    pub(crate) fn global(value: T) -> Self {
        Self {
            global: value.clone(),
            consumers: value,
        }
    }
}

impl FilterResult<bool> {
    pub(crate) fn combine(self, other: Self) -> Self {
        Self {
            global: self.global && other.global,
            consumers: self.consumers || other.consumers,
        }
    }
    pub(crate) fn result(&self) -> bool {
        self.global && self.consumers
    }
}

fn and_interest(a: Interest, b: Interest) -> Interest {
    if a.is_never() || b.is_never() {
        Interest::never()
    } else if a.is_sometimes() || b.is_sometimes() {
        Interest::sometimes()
    } else {
        Interest::always()
    }
}

impl FilterResult<Interest> {
    pub(crate) fn combine(self, other: Self) -> Self {
        // Disagreement must run enabled, even if one consumer always wants the
        // item: the other consumers still need their individual decisions.
        let consumers = if self.consumers.is_never() && other.consumers.is_never() {
            Interest::never()
        } else if self.consumers.is_always() && other.consumers.is_always() {
            Interest::always()
        } else {
            Interest::sometimes()
        };
        Self {
            global: and_interest(self.global, other.global),
            consumers,
        }
    }
    pub(crate) fn result(&self) -> Interest {
        and_interest(self.global.clone(), self.consumers.clone())
    }
}

// None is an unknown upper bound, rather than a level below OFF.
pub(crate) fn restrict(a: Option<LevelFilter>, b: Option<LevelFilter>) -> Option<LevelFilter> {
    match (a, b) {
        (Some(a), Some(b)) => Some(std::cmp::min(a, b)),
        (a, b) => a.or(b),
    }
}

impl FilterResult<Option<LevelFilter>> {
    pub(crate) fn combine(self, other: Self) -> Self {
        Self {
            global: restrict(self.global, other.global),
            consumers: match (self.consumers, other.consumers) {
                (Some(a), Some(b)) => Some(std::cmp::max(a, b)),
                _ => None,
            },
        }
    }
    pub(crate) fn result(&self) -> Option<LevelFilter> {
        restrict(self.global, self.consumers)
    }
}

impl<L, F, S> Filtered<L, F, S> {
    /// Wraps a layer with a per-layer filter.
    pub fn new(layer: L, filter: F) -> Self {
        Self {
            layer,
            filter,
            id: FilterId::new(),
            interests: RwLock::new(HashMap::new()),
            revision: Arc::new(AtomicUsize::new(0)),
            _s: PhantomData,
        }
    }
    /// Returns the wrapped layer.
    pub fn inner(&self) -> &L {
        &self.layer
    }
    /// Returns the filter.
    pub fn filter(&self) -> &F {
        &self.filter
    }
    /// Returns a mutable reference to the filter.
    ///
    /// Rebuild the callsite interest cache after changing an installed filter,
    /// for example by making the change through a reload handle.
    pub fn filter_mut(&mut self) -> &mut F {
        self.interests.get_mut().expect("lock poisoned").clear();
        self.revision.fetch_add(1, Ordering::Release);
        &mut self.filter
    }
}

impl<L: Clone, F: Clone, S> Clone for Filtered<L, F, S> {
    fn clone(&self) -> Self {
        Self::new(self.layer.clone(), self.filter.clone())
    }
}

impl<S, L, F> Layer<S> for Filtered<L, F, S>
where
    S: Subscriber + for<'a> LookupSpan<'a>,
    L: Layer<S>,
    F: Filter<S> + 'static,
{
    fn register_callsite(&self, metadata: &'static Metadata<'static>) -> Interest {
        self.__callsite(metadata);
        Interest::always()
    }
    fn __callsite(&self, metadata: &'static Metadata<'static>) -> FilterResult<Interest> {
        let interest = self.filter.callsite_enabled(metadata);
        self.interests
            .write()
            .expect("lock poisoned")
            .insert(metadata.callsite(), interest.clone());
        self.revision.fetch_add(1, Ordering::Release);
        let inner = self.layer.__callsite(metadata).result();
        FilterResult {
            global: Interest::always(),
            consumers: and_interest(interest, inner),
        }
    }
    fn __enabled(
        &self,
        metadata: &Metadata<'_>,
        ctx: Context<'_, S>,
        filters: &mut FilterMap,
    ) -> FilterResult<bool> {
        filters.watch(&self.revision);
        let ctx = ctx.with_filter(self.id);
        let interest = self
            .interests
            .read()
            .expect("lock poisoned")
            .get(&metadata.callsite())
            .cloned();
        let enabled = match interest {
            Some(ref interest) if interest.is_always() => true,
            Some(ref interest) if interest.is_never() => false,
            _ => self.filter.enabled(metadata, &ctx),
        };
        let enabled = enabled && self.layer.__enabled(metadata, ctx, filters).result();
        if enabled {
            filters.enable(self.id);
        }
        FilterResult {
            global: true,
            consumers: enabled,
        }
    }
    fn max_level_hint(&self) -> Option<LevelFilter> {
        restrict(
            self.filter.max_level_hint(),
            self.layer.__max_level_hint().result(),
        )
    }
    fn __max_level_hint(&self) -> FilterResult<Option<LevelFilter>> {
        FilterResult {
            global: None,
            consumers: self.max_level_hint(),
        }
    }
    fn new_span(&self, attrs: &span::Attributes<'_>, id: &span::Id, ctx: Context<'_, S>) {
        if !current_enabled(self.id) {
            return;
        }
        if let Some(span) = ctx.span(id) {
            let span = span.with_filter(&[self.id]);
            if !span.is_enabled() {
                // Registry stores this alongside the span. Existing custom
                // SpanData implementations use their extensions instead.
                span.extensions_mut().replace(current_filters());
            }
        }
        let ctx = ctx.with_filter(self.id);
        if ctx.span(id).is_some() {
            self.layer.new_span(attrs, id, ctx);
        }
    }
    fn on_event(&self, event: &Event<'_>, ctx: Context<'_, S>) {
        if current_enabled(self.id) {
            self.layer.on_event(event, ctx.with_filter(self.id));
        }
    }
    fn on_record(&self, id: &span::Id, values: &span::Record<'_>, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(id).is_some() {
            self.layer.on_record(id, values, ctx);
        }
    }
    fn on_follows_from(&self, id: &span::Id, follows: &span::Id, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(id).is_some() && ctx.span(follows).is_some() {
            self.layer.on_follows_from(id, follows, ctx);
        }
    }
    fn on_enter(&self, id: &span::Id, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(id).is_some() {
            self.layer.on_enter(id, ctx);
        }
    }
    fn on_exit(&self, id: &span::Id, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(id).is_some() {
            self.layer.on_exit(id, ctx);
        }
    }
    fn on_close(&self, id: span::Id, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(&id).is_some() {
            self.layer.on_close(id, ctx);
        }
    }
    fn on_id_change(&self, old: &span::Id, new: &span::Id, ctx: Context<'_, S>) {
        let ctx = ctx.with_filter(self.id);
        if ctx.span(old).is_some() {
            self.layer.on_id_change(old, new, ctx);
        }
    }
    unsafe fn downcast_raw(&self, id: TypeId) -> Option<*const ()> {
        if id == TypeId::of::<Self>() {
            Some(self as *const _ as *const ())
        } else if id == TypeId::of::<FilterMarker>() {
            Some(&FILTER_MARKER as *const _ as *const ())
        } else if id == TypeId::of::<F>() {
            Some(&self.filter as *const _ as *const ())
        } else {
            self.layer.downcast_raw(id)
        }
    }
}

impl<S> Filter<S> for LevelFilter {
    fn enabled(&self, metadata: &Metadata<'_>, _: &Context<'_, S>) -> bool {
        metadata.level() <= self
    }
    fn callsite_enabled(&self, metadata: &'static Metadata<'static>) -> Interest {
        if metadata.level() <= self {
            Interest::always()
        } else {
            Interest::never()
        }
    }
    fn max_level_hint(&self) -> Option<LevelFilter> {
        Some(*self)
    }
}

// Subscriber cannot expose the distinction between a global veto and a branch
// with no interested consumers. These slots pass that distinction between
// adjacent Layered subscribers without changing tracing-core's Subscriber API.
// Entries are tagged with their producer, so custom subscribers remain global.
struct Enabled {
    owner: Owner,
    callsite: Identifier,
    result: FilterResult<bool>,
    filters: FilterMap,
}
#[derive(Clone)]
struct Dispatching {
    next: Owner,
    callsite: Identifier,
    filters: FilterMap,
}
thread_local! {
    static ENABLED: RefCell<Option<Enabled>> = RefCell::new(None);
    static INTEREST: RefCell<Option<(Owner, FilterResult<Interest>)>> = RefCell::new(None);
    static HINT: RefCell<Option<(Owner, FilterResult<Option<LevelFilter>>)>> = RefCell::new(None);
    static DISPATCHING: RefCell<Option<Dispatching>> = RefCell::new(None);
}
// A transparent subscriber wrapper can have the same address as its inner
// subscriber, but must still be allowed to override that subscriber's result.
type Owner = (TypeId, usize);
fn owner<S: 'static>(subscriber: &S) -> Owner {
    (TypeId::of::<S>(), subscriber as *const S as usize)
}
pub(crate) fn is_registry<S: 'static>() -> bool {
    TypeId::of::<S>() == TypeId::of::<crate::Registry>()
}

pub(crate) fn subscriber_enabled<S: Subscriber>(
    subscriber: &S,
    metadata: &Metadata<'_>,
    filters: &mut FilterMap,
) -> FilterResult<bool> {
    ENABLED.with(|slot| slot.borrow_mut().take());
    let enabled = subscriber.enabled(metadata);
    if let Some(inner) = ENABLED.with(|slot| slot.borrow_mut().take()) {
        if inner.owner == owner(subscriber) && inner.callsite == metadata.callsite() {
            filters.extend(inner.filters);
            return inner.result;
        }
    }
    FilterResult {
        global: enabled,
        consumers: enabled && !is_registry::<S>(),
    }
}
pub(crate) fn publish_enabled<S: 'static>(
    subscriber: &S,
    metadata: &Metadata<'_>,
    result: FilterResult<bool>,
    filters: FilterMap,
    filtered: bool,
) -> bool {
    let enabled = if filtered {
        result.result()
    } else {
        result.global
    };
    ENABLED.with(|slot| {
        *slot.borrow_mut() = Some(Enabled {
            owner: owner(subscriber),
            callsite: metadata.callsite(),
            result,
            filters,
        })
    });
    enabled
}
pub(crate) fn subscriber_interest<S: Subscriber>(
    subscriber: &S,
    metadata: &'static Metadata<'static>,
) -> FilterResult<Interest> {
    INTEREST.with(|slot| slot.borrow_mut().take());
    let interest = subscriber.register_callsite(metadata);
    if let Some((id, result)) = INTEREST.with(|slot| slot.borrow_mut().take()) {
        if id == owner(subscriber) {
            return result;
        }
    }
    FilterResult::global(interest)
}
pub(crate) fn publish_interest<S: 'static>(
    subscriber: &S,
    result: FilterResult<Interest>,
    filtered: bool,
) -> Interest {
    let interest = if filtered {
        result.result()
    } else {
        result.global.clone()
    };
    INTEREST.with(|slot| *slot.borrow_mut() = Some((owner(subscriber), result)));
    interest
}
pub(crate) fn subscriber_hint<S: Subscriber>(subscriber: &S) -> FilterResult<Option<LevelFilter>> {
    HINT.with(|slot| slot.borrow_mut().take());
    let hint = subscriber.max_level_hint();
    if let Some((id, result)) = HINT.with(|slot| slot.borrow_mut().take()) {
        if id == owner(subscriber) {
            return result;
        }
    }
    if is_registry::<S>() {
        FilterResult {
            global: None,
            consumers: Some(LevelFilter::OFF),
        }
    } else {
        FilterResult::global(hint)
    }
}
pub(crate) fn publish_hint<S: 'static>(
    subscriber: &S,
    result: FilterResult<Option<LevelFilter>>,
    filtered: bool,
) -> Option<LevelFilter> {
    let hint = if filtered {
        result.result()
    } else {
        result.global
    };
    HINT.with(|slot| *slot.borrow_mut() = Some((owner(subscriber), result)));
    hint
}

pub(crate) struct DispatchGuard(Option<Dispatching>);
impl DispatchGuard {
    pub(crate) fn new<S: Subscriber, I: 'static>(
        subscriber: &S,
        inner: &I,
        metadata: &Metadata<'_>,
    ) -> Self {
        let inherited = DISPATCHING.with(|slot| {
            slot.borrow()
                .as_ref()
                .filter(|frame| {
                    frame.next == owner(subscriber) && frame.callsite == metadata.callsite()
                })
                .map(|frame| frame.filters.clone())
        });
        let filters = inherited.unwrap_or_else(|| {
            let pending = ENABLED.with(|slot| slot.borrow_mut().take());
            if let Some(pending) = pending {
                if pending.owner == owner(subscriber)
                    && pending.callsite == metadata.callsite()
                    && pending.filters.is_current()
                {
                    return pending.filters;
                }
            }
            // An always-interest callsite skips enabled. Populate span views
            // using the cached stable filter decisions in that case.
            subscriber.enabled(metadata);
            ENABLED.with(|slot| {
                slot.borrow_mut()
                    .take()
                    .map(|state| state.filters)
                    .unwrap_or_default()
            })
        });
        Self(DISPATCHING.with(|slot| {
            slot.replace(Some(Dispatching {
                next: owner(inner),
                callsite: metadata.callsite(),
                filters,
            }))
        }))
    }
}
impl Drop for DispatchGuard {
    fn drop(&mut self) {
        DISPATCHING.with(|slot| slot.replace(self.0.take()));
    }
}
pub(crate) fn current_filters() -> FilterMap {
    // Spans keep their original view for their entire lifetime, even after a
    // reload. Only pending event/span creation decisions need revision checks.
    DISPATCHING.with(|slot| {
        slot.borrow()
            .as_ref()
            .map(|frame| FilterMap {
                enabled: frame.filters.enabled.clone(),
                revisions: Vec::new(),
            })
            .unwrap_or_default()
    })
}
fn current_enabled(id: FilterId) -> bool {
    DISPATCHING.with(|slot| {
        slot.borrow()
            .as_ref()
            .map(|frame| frame.filters.is_enabled(id))
            .unwrap_or(false)
    })
}
