impl<A, B, S> fmt::Debug for Layered<A, B, S>
where
    A: fmt::Debug,
    B: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let alt = f.alternate();
        let mut s = f.debug_struct("Layered");
        s.field("layer", &self.layer).field("inner", &self.inner);
        if alt {
            s.field(
                "subscriber",
                &format_args!("PhantomData<{}>", type_name::<S>()),
            );
        };
        s.finish()
    }
}

