                .layer
                .__max_level_hint()
                .combine(layer_filters::subscriber_hint(&self.inner));
            return layer_filters::publish_hint(self, result, self.has_filters());
        }
        #[cfg(not(feature = "registry"))]
        std::cmp::max(self.layer.max_level_hint(), self.inner.max_level_hint())
