def toml(v):
    if isinstance(v,dict): return '{'+','.join(json.dumps(k)+'='+toml(x) for k,x in v.items())+'}'
    if isinstance(v,list): return '['+','.join(toml(x) for x in v)+']'
    return json.dumps(v)

