#[derive(Clone, Default)]
struct LookupProbe(Arc<Mutex<Option<span::Id>>>);
impl<S> Layer<S> for LookupProbe
where
    S: Subscriber + for<'a> LookupSpan<'a>,
{
    fn on_event(&self, _: &Event<'_>, ctx: Context<'_, S>) {
        let id = self.0.lock().unwrap().clone().unwrap();
        assert!(ctx.span(&id).is_none());
        assert!(ctx.metadata(&id).is_none());
        assert!(!ctx.exists(&id));
        assert_eq!(
            ctx.span_scope(&id)
                .unwrap()
                .map(|s| s.name())
                .collect::<Vec<_>>(),
            vec!["visible_root"]
        );
    }
}

#[test]
fn explicit_lookup_hides_a_span_but_scope_keeps_its_visible_ancestors() {
    let probe = LookupProbe::default();
    let subscriber = Registry::default()
        .with(
            probe
                .clone()
                .with_filter(filter_fn(|m| m.name() != "hidden")),
        )
        .with(Recorder::default());
    tracing::subscriber::with_default(subscriber, || {
        let _root = tracing::info_span!("visible_root").entered();
        let hidden = tracing::info_span!("hidden");
        *probe.0.lock().unwrap() = hidden.id();
        let _hidden = hidden.enter();
        tracing::info!("probe");
    });
}

struct GlobalVeto<S>(S);
