#[cfg(feature = "env-filter")]
#[test]
fn dynamic_global_filters_keep_the_spans_needed_to_enable_events() {
    let output = Recorder::default();
    let subscriber = Registry::default()
        .with(output.clone().with_filter(filter_fn(|m| m.is_event())))
        .with(tracing_subscriber::EnvFilter::new("[context]=info"));
    tracing::subscriber::with_default(subscriber, || {
        tracing::info!(target: "outside", "disabled");
        {
            let _span = tracing::info_span!("context").entered();
            tracing::info!(target: "inside", "enabled");
        }
        tracing::info!(target: "outside", "disabled again");
    });
    assert_eq!(output.entries(), vec!["event:inside:"]);
}

