#[test]
fn existing_custom_span_data_gets_the_same_filtered_view() {
    let output = Recorder::default();
    let subscriber = CustomRegistry(Registry::default()).with(
        output
            .clone()
            .with_filter(filter_fn(|m| m.name() != "hidden")),
    );
    tracing::subscriber::with_default(subscriber, || {
        let _root = tracing::info_span!("visible_root").entered();
        let _hidden = tracing::info_span!("hidden").entered();
        tracing::info!(target: "custom", "event");
    });
    assert!(!output
        .entries()
        .iter()
        .any(|entry| entry.ends_with(":hidden")));
    assert!(output
        .entries()
        .contains(&"event:custom:visible_root".to_owned()));
}

#[test]
fn replacing_a_whole_filtered_layer_invalidates_its_pending_decision() {
    let output = Recorder::default();
    let (layer, handle) =
        tracing_subscriber::reload::Layer::new(output.clone().with_filter(LevelFilter::OFF));
    let dispatch = tracing::Dispatch::new(Registry::default().with(layer));
    assert!(!dispatch.enabled(&MANUAL_META));
    handle
        .reload(output.clone().with_filter(LevelFilter::INFO))
        .unwrap();
    let values = MANUAL_META.fields().value_set(&[]);
    dispatch.event(&Event::new(&MANUAL_META, &values));
    assert_eq!(output.entries(), vec!["event:manual:"]);
}

#[test]
fn static_callsite_interests_cache_only_agreeing_branches() {
    let subscriber = Registry::default()
        .with(Recorder::default().with_filter(LevelFilter::TRACE))
        .with(Recorder::default().with_filter(LevelFilter::INFO));
    assert!(subscriber.register_callsite(&MANUAL_META).is_always());
    let subscriber = Registry::default()
        .with(Recorder::default().with_filter(LevelFilter::ERROR))
        .with(Recorder::default().with_filter(LevelFilter::OFF));
    assert!(subscriber.register_callsite(&MANUAL_META).is_never());
    let subscriber = Registry::default()
        .with(Recorder::default().with_filter(LevelFilter::INFO))
        .with(Recorder::default().with_filter(LevelFilter::OFF));
    assert!(subscriber.register_callsite(&MANUAL_META).is_sometimes());
}
